import sys

def main():
    data = sys.stdin.read().split()
    p = data[0]
    m = int(data[1])
    words = data[2:2 + m]
    if len(p) != m:
        print('false')
        return
    fwd, back = {}, {}
    for c, w in zip(p, words):
        if fwd.setdefault(c, w) != w or back.setdefault(w, c) != c:
            print('false')
            return
    print('true')

